import operator

def partial(fn, *partial_args, **partial_kwargs):
    def wrapper(*args, **kwargs):
        merged = {**partial_kwargs, **kwargs}
        return fn(*partial_args, *args, **merged)
    return wrapper


# -----------------------------------------------------------------------------
# Happy Path
# -----------------------------------------------------------------------------

def test_partial_with_single_positional_arg():
    add_5 = partial(operator.add, 5)
    assert add_5(10) == 15


def test_partial_with_multiple_positional_args():
    def concat(a, b, c):
        return f"{a}-{b}-{c}"

    fn = partial(concat, "A", "B")
    assert fn("C") == "A-B-C"


def test_partial_with_kwargs():
    def greet(name, greeting="Hello"):
        return f"{greeting}, {name}!"

    fn = partial(greet, greeting="Hi")
    assert fn("World") == "Hi, World!"


def test_partial_with_positional_and_keyword_args():
    def make_tag(text, tag="span", cls=None):
        attrs = f' class="{cls}"' if cls else ""
        return f"<{tag}{attrs}>{text}</{tag}>"

    fn = partial(make_tag, "hello", tag="div")
    assert fn(cls="active") == '<div class="active">hello</div>'


def test_partial_with_no_args_or_kwargs():
    """When nothing is pre-filled, wrapper should act as a pass-through."""
    fn = partial(operator.add)
    assert fn(3, 4) == 7


def test_partial_all_args_filled_no_call_args():
    def add3(a, b, c):
        return a + b + c

    fn = partial(add3, 1, 2, 3)
    assert fn() == 6


# -----------------------------------------------------------------------------
# Edge Cases
# -----------------------------------------------------------------------------

def test_kwargs_override():
    """Call-time kwargs should shadow pre-filled kwargs."""
    def config(host, port=8080, debug=False):
        return (host, port, debug)

    fn = partial(config, "localhost", port=3000)
    assert fn(port=5000, debug=True) == ("localhost", 5000, True)


def test_positional_and_variadic_accumulation():
    def gather(*args, **kwargs):
        return (args, kwargs)

    fn = partial(gather, 1, 2, x="a")
    args, kwargs = fn(3, y="b")
    assert args == (1, 2, 3)
    assert kwargs == {"x": "a", "y": "b"}


def test_chained_partials():
    def add(a, b, c, d):
        return a + b + c + d

    fn1 = partial(add, 1)
    fn2 = partial(fn1, 2)
    assert fn2(3, 4) == 10


def test_keyword_only_arguments():
    def kw_only(*, x, y):
        return (x, y)

    fn = partial(kw_only, x=10)
    assert fn(y=20) == (10, 20)


def test_partial_on_builtin_constructor():
    fn = partial(dict, a=1)
    assert fn(b=2) == {"a": 1, "b": 2}


def test_empty_call_on_zero_arg_function():
    fn = partial(lambda: 42)
    assert fn() == 42


